def countSubgraphsForEachDiameter(n: int, edges: list[list[int]]) -> list[int]:
    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(n): dist[i][i] = 0
    adj = [[] for _ in range(n)]
    for u, v in edges:
        u -= 1; v -= 1
        dist[u][v] = dist[v][u] = 1
        adj[u].append(v); adj[v].append(u)
    for k in range(n):
        for i in range(n):
            for j in range(n):
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])
    ans = [0] * (n - 1)
    for mask in range(1, 1 << n):
        nodes = [i for i in range(n) if (mask & (1 << i))]
        if len(nodes) < 2: continue
        edge_count = 0
        for u, v in edges:
            if (mask & (1 << (u - 1))) and (mask & (1 << (v - 1))):
                edge_count += 1
        if edge_count != len(nodes) - 1: continue
        q = [nodes[0]]
        visited = {nodes[0]}
        while q:
            curr = q.pop(0)
            for neighbor in adj[curr]:
                if (mask & (1 << neighbor)) and neighbor not in visited:
                    visited.add(neighbor)
                    q.append(neighbor)
        if len(visited) != len(nodes): continue
        max_d = 0
        for i in nodes:
            for j in nodes:
                max_d = max(max_d, dist[i][j])
        if 1 <= max_d <= n - 1:
            ans[max_d - 1] += 1
    return ans

